-- 03 — CONFERÊNCIA (somente leitura). Depois do 02: 37 migrações; a 0037 com o hash do Git; as 4 ações na lista; 9 funções e
-- 4 gatilhos novos. Depois do 04: SÓ as 2 concessões do MOVA (Açaí no Grau Saci, Subway Saci) com as 4 ações; nenhuma com sangria.
select (select count(*) from financeiro_v2.fv2_migracao) migracoes,
       (select bool_or(nome = '0037_operacoes_de_conta_a_pagar.sql') from financeiro_v2.fv2_migracao) tem_0037,
       (select bool_and(sha256 = 'd35d12cca2c55001cdf8925cc640bcfaee8a94e02b92ba008e799150d1255e44' and sha256_aplicado = 'd35d12cca2c55001cdf8925cc640bcfaee8a94e02b92ba008e799150d1255e44') from financeiro_v2.fv2_migracao where nome = '0037_operacoes_de_conta_a_pagar.sql') hash_confere,
       (select pg_get_constraintdef(oid) like '%reclassificar_conta_a_pagar%' and pg_get_constraintdef(oid) like '%ajustar_conta_a_pagar%' and pg_get_constraintdef(oid) like '%mover_competencia_conta_a_pagar%' and pg_get_constraintdef(oid) like '%cancelar_conta_a_pagar%' from pg_constraint where conname = 'fv2_concessao_acoes_lista') acoes_na_lista,
       (select count(*) from pg_proc where proname in ('fv2_pode_estreita', 'fv2_periodo_estreito', 'fv2_compra_elegivel', 'fv2_colunas_alteradas', 'fv2_forma_estreita_da_conta', 'fv2_lancamento_operacao_estreita', 'fv2_ajuste_estreito_confere', 'fv2_conta_estreita_coerente', 'fv2_ajuste_estreito')) funcoes_novas,
       (select count(*) from pg_trigger where tgname in ('fv2_lancamento_operacao_estreita', 'fv2_lancamento_ajuste_estreito', 'fv2_ajuste_estreito', 'fv2_obrigacao_estreita_coerente')) gatilhos_novos,
       (select count(*) from financeiro_v2.fv2_concessao where acoes ?| array['financeiro_v2.reclassificar_conta_a_pagar', 'financeiro_v2.ajustar_conta_a_pagar', 'financeiro_v2.mover_competencia_conta_a_pagar', 'financeiro_v2.cancelar_conta_a_pagar']) concessoes_com_as_acoes,
       (select count(*) from financeiro_v2.fv2_concessao where acoes ?| array['financeiro_v2.reclassificar_conta_a_pagar', 'financeiro_v2.ajustar_conta_a_pagar', 'financeiro_v2.mover_competencia_conta_a_pagar', 'financeiro_v2.cancelar_conta_a_pagar'] and not (usuario_id = '839a6da8-649d-4b6f-81c7-cb51c5c919cd' and (organizacao_id, unidade_id) in (('e7216085-1ece-45dc-bc41-d74f11a88e40'::uuid, '4d3b75bd-79b5-4335-ae5b-a183580c3555'::uuid), ('00000000-0000-0000-0000-000000000001'::uuid, '00000000-0000-0000-0000-0000000000a1'::uuid)))) fora_do_alcance,
       (select count(*) from financeiro_v2.fv2_concessao where usuario_id = '839a6da8-649d-4b6f-81c7-cb51c5c919cd' and acoes ? 'financeiro_v2.prestar_sangria') com_sangria;
